(()=>{
"use strict";
const assets={"labor-day":"data:image/webp;base64,","patriot-day":"data:image/webp;base64,","halloween":"data:image/webp;base64,","veterans-day":"data:image/webp;base64,","thanksgiving":"data:image/webp;base64,","christmas-hanukkah":"data:image/webp;base64,","new-years-day":"data:image/webp;base64,","mlk-day":"data:image/webp;base64,","valentines-day":"data:image/webp;base64,","presidents-day":"data:image/webp;base64,","st-patricks-day":"data:image/webp;base64,","easter":"data:image/webp;base64,","mothers-day":"data:image/webp;base64,","armed-forces-day":"data:image/webp;base64,","memorial-day":"data:image/webp;base64,","flag-day":"data:image/webp;base64,","fathers-day":"data:image/webp;base64,","juneteenth":"data:image/webp;base64,","independence-day":"data:image/webp;base64,","military-spouse-day":"data:image/webp;base64,"};
const nthWeekday=(year,month,weekday,n)=>{const d=new Date(year,month,1),delta=(weekday-d.getDay()+7)%7;return new Date(year,month,1+delta+7*(n-1));};
const lastWeekday=(year,month,weekday)=>{const d=new Date(year,month+1,0),delta=(d.getDay()-weekday+7)%7;return new Date(year,month,d.getDate()-delta);};
const easter=(year)=>{const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31)-1,day=((h+l-7*m+114)%31)+1;return new Date(year,month,day);};
const mothers=(year)=>nthWeekday(year,4,0,2);
const militarySpouse=(year)=>{const d=mothers(year);d.setDate(d.getDate()-2);return d;};
const definitions=[
["new-years-day","New Year's Day",y=>new Date(y,0,1)],
["mlk-day","Martin Luther King Jr. Day",y=>nthWeekday(y,0,1,3)],
["valentines-day","Valentine's Day",y=>new Date(y,1,14)],
["presidents-day","Presidents Day",y=>nthWeekday(y,1,1,3)],
["st-patricks-day","St. Patrick's Day",y=>new Date(y,2,17)],
["easter","Easter",y=>easter(y)],
["military-spouse-day","Military Spouse Appreciation Day",y=>militarySpouse(y)],
["mothers-day","Mother's Day",y=>mothers(y)],
["armed-forces-day","Armed Forces Day",y=>nthWeekday(y,4,6,3)],
["memorial-day","Memorial Day",y=>lastWeekday(y,4,1)],
["flag-day","Flag Day",y=>new Date(y,5,14)],
["fathers-day","Father's Day",y=>nthWeekday(y,5,0,3)],
["juneteenth","Juneteenth",y=>new Date(y,5,19)],
["independence-day","Independence Day",y=>new Date(y,6,4)],
["labor-day","Labor Day",y=>nthWeekday(y,8,1,1)],
["patriot-day","Patriot Day",y=>new Date(y,8,11)],
["halloween","Halloween",y=>new Date(y,9,31)],
["veterans-day","Veterans Day",y=>new Date(y,10,11)],
["thanksgiving","Thanksgiving",y=>nthWeekday(y,10,4,4)],
["christmas-hanukkah","Christmas & Hanukkah",y=>new Date(y,11,25)]
];
const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());
let choices=[];
for(let year=today.getFullYear();year<=today.getFullYear()+1;year++){for(const [key,name,getDate] of definitions){choices.push({key,name,date:getDate(year)});}}
choices.sort((a,b)=>a.date-b.date);
const active=choices.find(item=>item.date>=today)||choices[0];
const section=document.createElement("section");
section.className="holidayAccent";
section.setAttribute("aria-label",active.name+" holiday theme");
const image=document.createElement("img");
image.src=assets[active.key];
image.alt=active.name+" holiday decoration";
image.loading="lazy";
const label=document.createElement("div");
label.className="holidayName";
label.textContent=active.name;
section.append(image,label);
const marker=document.querySelector(".patriotBottom");
if(marker&&marker.parentNode){marker.parentNode.insertBefore(section,marker);}
})();